export function createTest(
	text: string,
	config: Partial<EngineConfig> = {}
): TestState {
	const merged: EngineConfig = { ...DEFAULT_ENGINE_CONFIG, ...config };
	const normalized = normalizeText(text);
	const lines = normalized
		.split("\n")
		.map((expected) => createLine(expected, merged.autoIndent));
	return {
		config: merged,
		text: normalized,
		lines,
		lineIndex: 0,
		status: "idle",
		startedAt: null,
		finishedAt: null,
		failReason: null,
		keyLog: [],
		keypresses: { correct: 0, incorrect: 0 },
	};
}

export function applyKey(state: TestState, event: KeyEvent): TestState {
	if (state.status === "finished" || state.status === "failed") {
		return state;
	}
	switch (event.type) {
		case "char":
			return applyChar(state, event.char, event.time);
		case "enter":
			return applyEnter(state, event.time);
		case "tab":
			return applyTab(state, event.time);
		case "backspace":
			return applyBackspace(state, event.word, event.time);
		default:
			return state;
	}
}

export type TestStatus = "idle" | "running" | "finished" | "failed";

export interface TestState {
	config: EngineConfig;
	text: string;
	lines: LineState[];
	lineIndex: number;
	status: TestStatus;
	/** Timestamp of the first scored keypress, or null before the test starts. */
	startedAt: number | null;
	finishedAt: number | null;
	failReason: string | null;
	keyLog: KeyLogEntry[];
	/** Counters that are updated on every keypress. */
	keypresses: { correct: number; incorrect: number };
}

dispatch: (event) => {
	const current = get().test;
	if (!current) {
		return null;
	}
	const next = applyKey(current, event);
	if (next !== current) {
		set({ test: next });
	}
	return next;
},

function leadingIndent(expected: string): string {
	return LEADING_WHITESPACE.exec(expected)?.[0] ?? "";
}

function createLine(expected: string, autoIndent: boolean): LineState {
	const indent = autoIndent ? leadingIndent(expected) : "";
	return { expected, typed: indent, skipped: indent.length, submitted: false };
}

function applyEnter(state: TestState, time: number): TestState {
	const line = state.lines[state.lineIndex];
	if (!line) {
		return state;
	}
	const isLast = state.lineIndex === state.lines.length - 1;
	if (isLast) {
		return state;
	}
	const nothingTyped = line.typed.length === line.skipped;
	if (nothingTyped && line.expected.trim() !== "") {
		return state;
	}
	const correct = line.typed === line.expected;
	if (!correct && state.config.stopOnError === "line") {
		return withKeypress(state, time, false);
	}
	if (!correct && state.config.difficulty === "expert") {
		return fail(
			withKeypress(state, time, false),
			time,
			"expert mode: incorrect line"
		);
	}
	const next = withKeypress(state, time, correct);
	const submitted: LineState = { ...line, submitted: true };
	const lines = replaceLine(next.lines, next.lineIndex, submitted);
	return { ...next, lines, lineIndex: next.lineIndex + 1 };
}

function applyBackspace(
	state: TestState,
	word: boolean,
	time: number
): TestState {
	if (state.config.confidenceMode === "max") {
		return state;
	}
	const line = state.lines[state.lineIndex];
	if (!line) {
		return state;
	}
	if (line.typed.length > line.skipped) {
		const end = word
			? wordBoundary(line.typed, line.skipped)
			: line.typed.length - 1;
		const updated: LineState = { ...line, typed: line.typed.slice(0, end) };
		const next = withKeypress(state, time, true, true);
		return { ...next, lines: replaceLine(next.lines, next.lineIndex, updated) };
	}
	if (state.lineIndex === 0 || state.config.confidenceMode === "on") {
		return state;
	}
	const previous = state.lines[state.lineIndex - 1];
	if (!previous) {
		return state;
	}
	const canReturn =
		state.config.freedomMode || previous.typed !== previous.expected;
	if (!canReturn) {
		return state;
	}
	const reopened: LineState = { ...previous, submitted: false };
	const next = withKeypress(state, time, true, true);
	return {
		...next,
		lines: replaceLine(next.lines, next.lineIndex - 1, reopened),
		lineIndex: next.lineIndex - 1,
	};
}

function applyTab(state: TestState, time: number): TestState {
	let next = state;
	for (let i = 0; i < state.config.indentSize; i++) {
		const line = next.lines[next.lineIndex];
		if (!line || line.expected[line.typed.length] !== " ") {
			break;
		}
		next = applyChar(next, " ", time);
	}
	return next;
}

export type StopOnError = "off" | "letter" | "line";
export type Difficulty = "normal" | "expert" | "master";
export type ConfidenceMode = "off" | "on" | "max";

export interface EngineConfig {
	/** Stop the caret from advancing past an incorrect letter / line. */
	stopOnError: StopOnError;
	/** `expert` fails on an incorrect line, `master` fails on any wrong key. */
	difficulty: Difficulty;
	/**
	 * Skip leading indentation when moving to a new line. Skipped characters are
	 * not counted toward speed, so this never inflates results.
	 */
	autoIndent: boolean;
	/** Allow backspacing into lines that were already submitted correctly. */
	freedomMode: boolean;
	/** `on` disables backspacing into previous lines, `max` disables backspace. */
	confidenceMode: ConfidenceMode;
	/** Treat the Tab key as typing one indent unit of spaces. */
	indentSize: number;
}

function applyChar(state: TestState, char: string, time: number): TestState {
	const line = state.lines[state.lineIndex];
	if (!line) {
		return state;
	}
	const position = line.typed.length;
	const expected = line.expected[position];
	const ok = expected !== undefined && char === expected;
	const isLast = state.lineIndex === state.lines.length - 1;

	if (expected === undefined) {
		// Typing beyond the end of the line.
		if (isLast || position - line.expected.length >= MAX_EXTRA_CHARS) {
			return state;
		}
		if (state.config.stopOnError !== "off") {
			return state;
		}
	}

	if (!ok && state.config.difficulty === "master") {
		return fail(
			withKeypress(state, time, false),
			time,
			"master mode: incorrect key"
		);
	}

	let next = withKeypress(state, time, ok);
	if (!ok && state.config.stopOnError === "letter") {
		return next;
	}

	const updatedLine: LineState = { ...line, typed: line.typed + char };
	next = {
		...next,
		lines: replaceLine(next.lines, next.lineIndex, updatedLine),
	};

	if (isLast && isLineComplete(updatedLine, next.config.stopOnError)) {
		return { ...next, status: "finished", finishedAt: time };
	}
	return next;
}

const correct = line.typed === line.expected;
if (!correct && state.config.stopOnError === "line") {
	return withKeypress(state, time, false);
}
if (!correct && state.config.difficulty === "expert") {
	return fail(
		withKeypress(state, time, false),
		time,
		"expert mode: incorrect line"
	);
}

// Failed tests (expert/master) restart automatically after a short notice.
useEffect(() => {
	if (test?.status !== "failed") {
		return;
	}
	toast.error(test.failReason ?? "Test failed");
	const timer = window.setTimeout(repeatTest, 800);
	return () => window.clearTimeout(timer);
}, [test?.status, test?.failReason, repeatTest]);

export function countChars(lines: LineState[], lineIndex: number): CharCounts {
	const counts: CharCounts = {
		correct: 0,
		incorrect: 0,
		extra: 0,
		missed: 0,
		newlines: 0,
		skipped: 0,
	};
	lines.forEach((line, index) => {
		counts.skipped += line.skipped;
		const expected = line.expected;
		const typed = line.typed;
		for (let i = line.skipped; i < typed.length; i++) {
			if (i >= expected.length) {
				counts.extra++;
			} else if (typed[i] === expected[i]) {
				counts.correct++;
			} else {
				counts.incorrect++;
			}
		}
		if (line.submitted || index < lineIndex) {
			counts.missed += Math.max(0, expected.length - typed.length);
			if (index < lines.length - 1) {
				counts.newlines++;
			}
		}
	});
	return counts;
}

export function wpmFromChars(chars: number, durationMs: number): number {
	if (durationMs <= 0) {
		return 0;
	}
	return (chars / CHARS_PER_WORD) * (MS_PER_MINUTE / durationMs);
}

/**
 * monkeytype's consistency metric: 100 * (1 - tanh(cov + cov^3/3 + cov^5/5))
 * where cov is the coefficient of variation of the per-second raw speeds.
 */
export function kogasa(cov: number): number {
	const value = cov + cov ** 3 / 3 + cov ** 5 / 5;
	return PERCENT * (1 - Math.tanh(value));
}

export function computeStats(state: TestState, now?: number): TestStats {
	const start = state.startedAt;
	const end = state.finishedAt ?? now ?? start ?? 0;
	const durationMs = start === null ? 0 : Math.max(0, Math.round(end - start));
	const chars = countChars(state.lines, state.lineIndex);
	const totalKeypresses = state.keypresses.correct + state.keypresses.incorrect;
	const accuracy =
		totalKeypresses === 0
			? PERCENT
			: (state.keypresses.correct / totalKeypresses) * PERCENT;
	const correctScored = chars.correct + chars.newlines;
	const rawScored = correctScored + chars.incorrect + chars.extra;
	const chart = buildChart(state.keyLog, durationMs);
	const rawSpeeds = chart.map((p) => p.raw).filter((r) => r > 0);
	const consistency = kogasa(coefficientOfVariation(rawSpeeds));

	return {
		wpm: roundTo(wpmFromChars(correctScored, durationMs), 2),
		raw: roundTo(wpmFromChars(rawScored, durationMs), 2),
		accuracy: roundTo(accuracy, 2),
		consistency: roundTo(consistency, 2),
		durationMs,
		chars,
		chart,
	};
}

export function buildChart(
	keyLog: KeyLogEntry[],
	durationMs: number
): ChartPoint[] {
	const seconds = Math.max(1, Math.ceil(durationMs / MS_PER_SECOND));
	const perSecondChars = new Array<number>(seconds).fill(0);
	const perSecondErrors = new Array<number>(seconds).fill(0);
	let cumulativeCorrect = 0;
	const cumulativeBySecond = new Array<number>(seconds).fill(0);

	for (const entry of keyLog) {
