// Any key press while unfocused returns focus to the test.
useEffect(() => {
	const handler = (event: KeyboardEvent) => {
		if (document.activeElement === inputRef.current) {
			return;
		}
		const target = event.target as HTMLElement | null;
		const typingElsewhere =
			target &&
			(target.tagName === "INPUT" ||
				target.tagName === "TEXTAREA" ||
				target.isContentEditable ||
				target.closest("[cmdk-root]"));
		if (typingElsewhere || event.ctrlKey || event.metaKey) {
			return;
		}
		if (
			event.key.length === 1 ||
			event.key === "Enter" ||
			event.key === "Backspace"
		) {
			focusInput();
		}
	};
	window.addEventListener("keydown", handler);
	return () => window.removeEventListener("keydown", handler);
}, [focusInput]);

function toKeyEvent(
	event: React.KeyboardEvent<HTMLInputElement>,
	time: number
): KeyEvent | null {
	switch (event.key) {
		case "Backspace":
			return { type: "backspace", word: event.altKey, time };
		case "Enter":
			return { type: "enter", time };
		case "Tab":
			return { type: "tab", time };
		default:
			if (event.key.length !== 1 || event.altKey) {
				return null;
			}
			return { type: "char", char: event.key, time };
	}
}

// Position the caret on the active character.
useLayoutEffect(() => {
	const container = linesRef.current;
	const caret = caretRef.current;
	if (!(container && caret)) {
		return;
	}
	const line = container.querySelector<HTMLElement>(
		`[data-line="${test.lineIndex}"]`
	);
	if (!line) {
		return;
	}
	const col = test.lines[test.lineIndex]?.typed.length ?? 0;
	const chars = line.querySelectorAll<HTMLElement>(".char");
	const containerRect = container.getBoundingClientRect();
	let x: number;
	let y: number;
	let height: number;
	const target = chars[col];
	if (target) {
		const rect = target.getBoundingClientRect();
		x = rect.left - containerRect.left;
		y = rect.top - containerRect.top;
		height = rect.height;
	} else {
		const last = chars.item(chars.length - 1);
		const content = line.querySelector<HTMLElement>(".line-content");
		const rect = (last ?? content ?? line).getBoundingClientRect();
		x = (last ? rect.right : rect.left) - containerRect.left;
		y = rect.top - containerRect.top;
		height = rect.height;
	}
	caret.style.transform = `translate(${x}px, ${y}px)`;
	caret.style.height = `${height}px`;
}, [test]);

// Global shortcut: ctrl/cmd + shift + p
useEffect(() => {
	const handler = (event: KeyboardEvent) => {
		if (
			(event.ctrlKey || event.metaKey) &&
			event.shiftKey &&
			event.key.toLowerCase() === "p"
		) {
			event.preventDefault();
			if (open) {
				closePalette();
			} else {
				openPalette();
			}
		}
	};
	window.addEventListener("keydown", handler);
	return () => window.removeEventListener("keydown", handler);
}, [open, openPalette, closePalette]);

/** Handles tab/esc shortcuts. Returns true when the key was consumed. */
function handleShortcut(
	event: React.KeyboardEvent<HTMLInputElement>,
	quickRestart: UserConfig["quickRestart"],
	nextTest: () => void,
	openPalette: () => void
): boolean {
	if (event.key === "Tab" && quickRestart === "tab") {
		event.preventDefault();
		nextTest();
		return true;
	}
	if (event.key === "Escape") {
		event.preventDefault();
		if (quickRestart === "esc") {
			nextTest();
		} else {
			openPalette();
		}
		return true;
	}
	return false;
}

