/** Applies theme, font family and font size from the config to the document. */
export function useApplyAppearance() {
	const theme = useConfigStore((s) => s.config.theme);
	const fontFamily = useConfigStore((s) => s.config.fontFamily);
	const fontSize = useConfigStore((s) => s.config.fontSize);

	useEffect(() => {
		applyTheme(theme);
	}, [theme]);

	useEffect(() => {
		const root = document.documentElement;
		root.style.setProperty(
			"--test-font",
			FONT_VARS[fontFamily] ?? FONT_VARS["geist-mono"] ?? ""
		);
		root.style.setProperty("--test-font-size", `${fontSize}rem`);
	}, [fontFamily, fontSize]);
}

export function randomThemeName(
	mode: "on" | "light" | "dark",
	exclude?: string
): string {
	const pool = THEME_NAMES.filter((name) => {
		if (name === exclude) {
			return false;
		}
		if (mode === "on") {
			return true;
		}
		const light = isLightTheme(getTheme(name));
		return mode === "light" ? light : !light;
	});
	return pool[Math.floor(Math.random() * pool.length)] ?? "bushido";
}

